 const legend=mapShow==='diff'?diffLegend():sn==null?'':'<ol class="class-key">'+k.colors.map((c,i)=>{const kq=hKvot(),lo=i?sn*kq[i-1]:null,hi=i<kq.length?sn*kq[i]:null;return '<li><i style="background:'+c+'"></i>'+(lo==null?'under '+hFmt(hi):hi==null?'över '+hFmt(lo):hFmt(lo)+'–'+hFmt(hi))+'</li>';}).join('')+'</ol>';
