/* ===== 2.0.6: kartan visar basfall, scenario eller förändring (modell A och B) =====
   Kartan, tabellen och områdespanelen följer samma val. Scenariot kommer från senaste beräkningen
   (Beräkna med osäkerhet). Förändringen färgas i procent av basfallet med en tvåsidig skala. */
let mapShow='base';
const DIFF_CLASSES=[{max:-.2,color:'#145a4c',t:'minskar mer än 20 %'},{max:-.01,color:'#4f9e88',t:'minskar 1–20 %'},{max:.01,color:'#e4e7e4',t:'oförändrat (±1 %)'},{max:.2,color:'#f0a868',t:'ökar 1–20 %'},{max:1,color:'#d0632b',t:'ökar 20–100 %'},{max:Infinity,color:'#952e17',t:'ökar mer än 100 %'}];
function diffColor(rel){return rel==null||!Number.isFinite(rel)?'#c9d1cb':DIFF_CLASSES.find(c=>rel<=c.max).color;}
function diffLegend(){return '<ol class="class-key">'+DIFF_CLASSES.map(c=>'<li><i style="background:'+c.color+'"></i>'+c.t+'</li>').join('')+'</ol>';}
function hasScenario(){return (result?.results||[]).some(x=>x.central&&x.scenarioCentral&&Math.abs(x.scenarioCentral.total-x.central.total)>1e-9*Math.max(1,Math.abs(x.central.total)));}
function mapToggle(){return '<div class="toggle" role="group" aria-label="Visa i kartan">'+[['base','Basfall'],['scenario','Scenario'],['diff','Förändring']].map(([k,t])=>'<button type="button" data-mapshow="'+k+'" class="'+(mapShow===k?'active':'')+'" aria-pressed="'+(mapShow===k)+'">'+t+'</button>').join('')+'</div>';}
function mapNote(){if(mapShow==='base'){return result&&hasScenario()?'<div class="notice info">Senaste beräkningen har ett scenario som skiljer sig från basfallet. Välj <b>Scenario</b> eller <b>Förändring</b> för att se det i kartan.</div>':'';}
 if(!result)return '<div class="notice">Beräkna med osäkerhet för att se scenariot i kartan.</div>';
 if(!hasScenario())return '<div class="notice">Scenariot är lika med basfallet i senaste beräkningen. Ändra under Antaganden & scenario eller Åtgärder & underlag, och klicka Beräkna med osäkerhet.</div>';
 return dirty?'<div class="notice">Kartan visar den senaste beräkningen. Indata har ändrats sedan dess; klicka Beräkna med osäkerhet för att uppdatera kartan.</div>':'';}
function mapWhat(){return mapShow==='scenario'?'Kartan visar scenariot från senaste beräkningen.':mapShow==='diff'?'Kartan visar förändringen mellan basfall och scenario, i procent av basfallet.':'Kartan visar basfallet.';}
/* Modell B */
function hShowValue(x){if(mapShow==='scenario')return hValue(x,'scenarioCentral');if(mapShow==='diff'){const a=hValue(x),b=hValue(x,'scenarioCentral');return a==null||b==null?null:b-a;}return hValue(x);}
function hRel(x){const a=hValue(x),b=hValue(x,'scenarioCentral');return a&&b!=null?b/a-1:null;}
function hUnit(){const u=hScope==='direct'?'CO₂':'CO₂e',m=MEASURES[hMeasure];return m[1]+' '+u+(hMeasure==='totalt'?' per år':' '+m[0]);}
/* Modell A */
function aRel(x){const a=x?.central?.total,b=x?.scenarioCentral?.total;return a&&b!=null?b/a-1:null;}
function aMax(){return Math.max(1,...(result?.results||[]).filter(x=>x.city===currentCity&&x.level===currentLevel).map(x=>aVal(x)||0));}
function aFill(x,max){if(mapShow==='diff')return diffColor(aRel(x));return window.VagvisMaps.color(aVal(x,mapShow==='scenario'?'scenarioCentral':'central'),max);}
function aTooltip(x,name){if(!x?.central)return esc(name)+' · trafik saknas';const y=areaHa(x),b=x.central.total,s=x.scenarioCentral?.total,ph=perHa(b,y);return '<b>'+esc(name||x.name)+'</b><br>'+(mapShow==='base'?'':'Basfall ')+num(b)+' ton CO₂e/år'+(ph!=null?' · '+fmtHa(ph)+' ton/ha':'')+(mapShow!=='base'&&s!=null?'<br>Scenario '+num(s)+' ton CO₂e/år ('+vpct(s/b-1)+')'+(ph!=null?' · '+fmtHa(perHa(s,y))+' ton/ha':''):'');}
/* Förvald DeSO i kartan när ett områdesscenario är aktivt */
function asMapId(){if(!AS?.active||AS.city!==currentCity||currentLevel!=='deso')return null;if(activeModel==='household')return AS.deso;const a=asADeso(AS);return a?a.id:null;}
/* ===== 2.0.5: Områdesscenario för en DeSO, i modell A och B =====
   En definition (AS) gäller båda modellerna och sparas i båda modellernas inställningar (cfg.areaScenario).
   B: hushållens bilar i DeSO:n med Bilmodell v7:s åtgärdsmodell (households.js: areaSetup, areaDetail, areaMC).
   A: de boendes ändrade biltrafik på DeSO:ns egna vägar (core.js: areaTraffic), räknad ur B gånger andelen av
   körningen som sker inom DeSO:n. Basfallet ändras inte i någon av modellerna. */
let paramTab='area',AS=null,_bp=null,_bc=null,_ap=null;
const AS_TRIP_KM=25,AS_BUDGET=160,AS_JAG={city:'1280',deso:'1280C1450',newDwellings:4000,persons:2};
/* Trivectors mobilitetsprinciper (rapport 2025:55) översatta till Bilmodell v7:s åtgärder. Tolkning gjord i Vägvis. */
const AS_STRATEGI={parkeringspris:100,mobilitetshus:100,gatuutrymme:100,kollektivtrafik:100,cykelnat:100,bilpool:60,radgivning:100};
const AS_STRATEGI_TABELL=[
 ['Rätt anpassade parkeringstal: cirka 0,3 bilar per hushåll (s. 7 och 18)','Parkeringstal 0,3 platser per bostad. Tak för bilar per hushåll; räknas som push när det begränsar.','0,3'],
 ['Parkering i mobilitetshus (s. 18)','Samlad parkering i mobilitetshus','100 %'],
 ['Rätt prissättning av bilparkering (s. 18)','Parkering prissätts separat och marknadsmässigt','100 %'],
 ['Delad mobilitet: bilpool för cirka 70 % av hushållen (s. 7 och 17)','Bilpool i fastigheten. 60 % är modellens högsta nivå; underlaget täcker inte 70 %.','60 %'],
 ['Låg hastighet som norm, gångfart och prioriterade gång- och cykelstråk (s. 16)','Omfördelat gatuutrymme, cirkulationsplan eller lågtrafikområde','100 %'],
 ['Gena, bekväma och trygga cykelstråk till och från området (s. 21)','Snabbcykelväg och sammanhängande cykelnät','100 %'],
 ['Mobilitetshubb XXL och kapacitetsstark kollektivtrafik, till exempel spårväg (s. 21)','Spårväg, BRT eller stomlinje med hög turtäthet','100 %'],
 ['Mobilitetsberättelse, mobilitetstjänster och introduktion för boende (s. 17 och 22)','Mobilitetsrådgivning, testresenär och testcyklist','100 %']];
function asStrategyState(){const o=window.BILMODELL.nyttAtgTillstand();for(const [k,v]of Object.entries(AS_STRATEGI))if(o[k])o[k]={pa:true,niva:v};return o;}
const AS_PRESETS={
 jagersro_ref:{namn:'Jägersro: referens utan mobilitetsstrategi',kort:'Referens utan strategi',text:'4 000 nya bostäder och 8 000 invånare (Trivector, s. 4 och 7). De nya hushållen får samma bilinnehav och körsträcka som i Hyllie, som är Bilmodell v7:s förval för Jägersro i fliken Nya områden. Inga åtgärder.',make:()=>({...AS_JAG,base:{mode:'analog',analog:{kk:'1280',sd:'Hyllie',kod:''},bph:null,km:null},parking:null,measures:{packageId:'inga',state:null},applyExisting:false})},
 jagersro_strategi:{namn:'Jägersro: mobilitetsstrategin som åtgärder',kort:'Strategin som åtgärder',text:'Samma utgångsläge som referensen. Mobilitetsstrategins principer är översatta till Bilmodell v7:s åtgärder och parkeringstalet 0,3 platser per bostad (tabellen längst ned). Modellen räknar då ut bilinnehav och körsträcka med v7:s effekter och osäkerheter.',make:()=>({...AS_JAG,base:{mode:'analog',analog:{kk:'1280',sd:'Hyllie',kod:''},bph:null,km:null},parking:.3,measures:{packageId:'trivector',state:asStrategyState()},applyExisting:false})},
 jagersro_mal:{namn:'Jägersro: Trivectors målnivå (0,3 bilar per hushåll)',kort:'Trivectors målnivå',text:'Trivectors egna antaganden (s. 7): 0,3 bilar per hushåll och 11 000 km per bil. Inga ytterligare åtgärder, eftersom målnivån redan förutsätter strategin.',make:()=>({...AS_JAG,base:{mode:'own',analog:null,bph:.3,km:11000},parking:null,measures:{packageId:'inga',state:null},applyExisting:false})}};
const AS_MODE_TEXT={area:'Som Bilmodell v7, fliken Befintliga områden: nya bostäder får områdets bilinnehav och körsträcka, med täthetseffekt.',analog:'Som Bilmodell v7, fliken Nya områden: de nya hushållen liknar ett annat befintligt område.',own:'Egna värden, till exempel målnivåer i en mobilitetsstrategi.'};
function asNew(city,deso,x={}){return {active:false,edited:false,presetId:'egen',city,deso,newDwellings:0,persons:null,base:{mode:'area',analog:null,bph:null,km:null},parking:null,ev:{el:null,lh:null},measures:{packageId:'inga',state:null},applyExisting:true,a:{share:null,tripKm:AS_TRIP_KM},budget:AS_BUDGET,newCV:.2,sigmaS:0,...x};}
function asPreset(id){return asNew(AS_JAG.city,AS_JAG.deso,{...AS_PRESETS[id].make(),active:true,edited:true,presetId:id});}
function bProj(){return activeModel==='household'?project:(states.household?.project||(_bp??=V.validateProject(initialHouseholdProject)));}
function bCfg(){return activeModel==='household'?cfg:(states.household?.cfg||(_bc??=V.config(initialHouseholdProject.config)));}
function aProj(){return activeModel==='territorial'?project:(states.territorial?.project||(_ap??=V.validateProject(initialProject)));}
function aCfg(){return activeModel==='territorial'?cfg:(states.territorial?.cfg||V.config(initialConfig));}
function aResult(){return activeModel==='territorial'?result:(states.territorial?.result||null);}
function aIsDirty(){return activeModel==='territorial'?dirty:(states.territorial?.dirty??true);}
function asBRow(s=AS){return s?bProj().households.find(r=>r.kk===s.city&&r.kod===s.deso)||null:null;}
function asSort(rows){return rows.slice().sort((a,b)=>(a.rs+a.kod).localeCompare(b.rs+b.kod,'sv'));}
function asDefaultRow(kk){const rows=bProj().households.filter(r=>r.kk===kk);return rows.find(r=>r.kod===AS_JAG.deso)||asSort(rows.filter(r=>r.sd===[...new Set(rows.map(x=>x.sd))].sort((a,b)=>a.localeCompare(b,'sv'))[0]))[0]||null;}
function asState(){if(!AS.measures)AS.measures={packageId:'inga',state:null};if(!AS.measures.state)AS.measures.state=window.BILMODELL.nyttAtgTillstand();return AS.measures.state;}
function asCfgB(s=AS){const c=V.clone(bCfg());c.areaScenario={...V.clone(s),active:true};return c;}
function asDetail(s=AS){try{const c=asCfgB(s);return {d:HH().areaDetail(bProj(),c),c};}catch(e){return {error:e.message};}}
/* DeSO i modell A (DeSO 2025): samma kod, annars den DeSO som innehåller B-områdets mittpunkt. */
function asADeso(s=AS){if(!s)return null;const p=aProj();if(!p.areas.some(a=>a.city===s.city&&a.level==='deso'))return null;let a=p.areas.find(x=>x.city===s.city&&x.level==='deso'&&x.id===s.deso);if(!a){const r=asBRow(s);if(r)a=p.areas.find(x=>x.city===s.city&&x.level==='deso'&&V.contains(x.geometry,[r.lon,r.lat]));}if(!a)return null;const b=V.bbox(a.geometry),pt=[(b[0]+b[2])/2,(b[1]+b[3])/2],dist=p.areas.find(x=>x.city===s.city&&x.level==='district'&&V.contains(x.geometry,pt));return {id:a.id,name:a.name&&a.name!==a.id?a.name:'',km2:V.areaKm2(a.geometry),exact:a.id===s.deso,district:dist?dist.id:null,districtName:dist?dist.name:''};}
/* Andel av de boendes bilkörning på DeSO:ns vägar: 1,1 × radien för en cirkel med DeSO:ns yta / reslängden.
   0,85 radier är medelsträckan från en slumpvis punkt till cirkelns kant i slumpvis riktning; 1,3 är en omvägsfaktor. */
function asShareDefault(aD,s=AS){return aD?Math.min(.5,1.1*Math.sqrt(aD.km2/Math.PI)/(Number(s.a?.tripKm)||AS_TRIP_KM)):null;}
function asShare(aD,s=AS){return s.a?.share!=null?s.a.share:asShareDefault(aD,s);}
/* De boendes ändrade fordonskm i DeSO:n, utan B:s kommunscenario för trafikarbete (A har sitt eget). */
function asDeltaV(d){return (d.old.vkm+(d.nu?d.nu.vkm:0))/(1+d.prep.c.trafficChange)-d.base.vkm;}
function asTraffic(){if(!AS||!AS.active)return null;const aD=asADeso(AS);if(!aD)return null;const x=asDetail();if(x.error)return null;return [{city:AS.city,deso:aD.id,carVkm:asDeltaV(x.d)*asShare(aD),label:'Områdesscenario '+AS.deso}];}
function asApply(model,c){if(!c)return c;delete c.areaTraffic;if(!AS||!AS.active){delete c.areaScenario;return c;}c.areaScenario=V.clone(AS);if(model==='territorial'){const t=asTraffic();if(t)c.areaTraffic=t;}return c;}
function asOther(){return activeModel==='household'?'territorial':'household';}
function asChanged(full,toggle=false){asApply(activeModel,cfg);const o=asOther();if(states[o]?.cfg)asApply(o,states[o].cfg);if(AS?.active||toggle){markDirty();if(states[o])states[o].dirty=true;}if(full)render();else asRefresh();}
function asTouch(){if(AS.presetId!=='egen'){AS.presetId='egen';if($('as-preset'))$('as-preset').value='egen';}if(!AS.edited){AS.edited=true;AS.active=true;if($('as-active'))$('as-active').checked=true;}}
function asOpt(v,t,sel){return '<option value="'+esc(v)+'"'+(String(v)===String(sel)?' selected':'')+'>'+esc(t)+'</option>';}
function asSgn(v,f=r7){return (v<0?'−':'+')+f(Math.abs(v));}
function asTile(t,v,c){return '<div><dt>'+t+'</dt><dd>'+v+'</dd>'+(c?'<dd class="m-chg">'+c+'</dd>':'')+'</div>';}
function asMkm(v){return num(v/1e6,v<1e6?2:1);}
function asOpenButton(kk,kod){return '<button type="button" class="secondary small-btn" data-as-open="'+esc(kk+'|'+kod)+'">Scenario för området →</button>';}
function asBForA(x){const B=bProj(),r=B.households.find(h=>h.kk===x.city&&h.kod===x.id);if(r)return r;const a=aProj().areas.find(z=>z.city===x.city&&z.level==='deso'&&z.id===x.id);if(!a)return null;const b=V.bbox(a.geometry),pt=[(b[0]+b[2])/2,(b[1]+b[3])/2],z=B.areas.find(q=>q.city===x.city&&q.level==='deso'&&V.contains(q.geometry,pt));return z?B.households.find(h=>h.kk===x.city&&h.kod===z.id)||null:null;}
function asNotice(){if(!AS||!AS.active)return '';const r=asBRow();return '<div class="notice info"><strong>Områdesscenario:</strong> scenariot innehåller DeSO '+esc(AS.deso)+(r?' ('+esc(r.rs)+')':'')+' i '+esc(cityName(AS.city))+(AS.newDwellings>0?' med '+num(AS.newDwellings)+' nya bostäder':'')+'. <a href="#parameters" data-as-goto="1">Öppna områdesscenariot →</a></div>';}
