function asMeasureList(st){const A=ATGd();let h='';for(const g of A.grupper){const ms=A.lista.filter(m=>m.grupp===g.id);if(!ms.length)continue;h+='<div class="m-group"><h3>'+esc(g.namn)+' <span class="m-group-roll">'+esc((A.roller||{})[g.roll]||'')+'</span></h3>'+ms.map(m=>{const x=st[m.id]||{pa:false,niva:m.standard};return '<div class="measure'+(x.pa?' on':'')+'"><label class="m-head"><input type="checkbox" data-astoggle="'+esc(m.id)+'" '+(x.pa?'checked':'')+'> <span class="m-name">'+esc(m.namn)+'</span> '+rollBadge(m.roll)+gradBadge(m.grad)+'</label><p class="m-short">'+esc(m.kort)+(m.endastNy?' Gäller bara nya bostäder.':'')+'</p><p class="m-effect">'+esc(effekttext(m))+'</p>'+(m.typ!=='binar'?'<div class="m-level"><input type="range" min="'+m.min+'" max="'+m.max+'" step="'+m.steg+'" value="'+x.niva+'" data-aslevel="'+esc(m.id)+'" '+(x.pa?'':'disabled')+' aria-label="Nivå för '+esc(m.namn)+'"><span id="asl-'+esc(m.id)+'">'+num(x.niva)+' % '+esc(m.nivaText)+'</span></div>':'')+'</div>';}).join('')+'</div>';}return h;}

