 h+='<div class="controls" style="margin-top:14px">'+hField('Klimatbudget, kg CO₂ per person och år','as-budget','data-as="budget"',num(AS.budget??AS_BUDGET),'Trivector (2025:55, s. 6–7): cirka 160 kg för bilfordonen 2025–2050, med stor osäkerhet.')+'</div></article>';
 h+='<article class="card" style="margin-top:18px"><div class="row wrap"><h2>Modell B · de boendes bilar</h2><span class="pill'+(AS.active?'':' amber')+'" id="as-status">'+(AS.active?'Med i beräkningen':'Förhandsvisning')+'</span></div><p class="card-sub">Direkt CO₂ räknas som i Bilmodell v7 (fliken Klimatpåverkan) och livscykeln som i modell B. Intervallen är 90 % och omfattar åtgärdernas effekter, utsläppsfaktorer, eldrift och kommunens fordonskm'+(mode!=='area'?' samt de nya hushållens utgångsläge':'')+', som i v7.</p><div id="as-b-live"></div></article>';
 const aD=asADeso(AS);
