  '<div id="as-m-live"></div>'+asMeasureList(st)+'</article>';
 if(AS.city===AS_JAG.city&&AS.deso===AS_JAG.deso)h+='<article class="card" style="margin-top:18px"><h2>Jägersro: förvalen jämförda</h2><p class="card-sub">Samma DeSO, centrala värden. Modell A visar ändringen av livscykelutsläppen på DeSO:ns vägar.</p><div id="as-cmp-live"></div></article>'+asSourceCard();
