function asSourceCard(){return '<article class="card" style="margin-top:18px"><h2>Underlag: Trivectors mobilitetsstrategi för Jägersro</h2><p class="card-sub">Trivector Traffic (2025). Mobilitetsstrategi Projekt Jägersro. Rapport 2025:55, version 1.0, 7 juli 2025. Beställare: SMT Malmö Exploatering AB.</p><div class="grid2 grid-even"><div><h3>Uppgifter som förvalen använder</h3><ul class="small as-list"><li>Drygt 40 hektar, drygt 4 000 bostäder och cirka 1 000 arbetsplatser; utbyggnad under cirka 25 år från omkring 2030 (s. 4).</li><li>Cirka 8 000 invånare (s. 7).</li><li>Klimatbudget för bilfordonen: under cirka 160 kg CO₂ per person och år 2025–2050, med stor osäkerhet; efter 2030 sannolikt lägre (s. 6–7).</li><li>Bilinnehav cirka 0,3 bilar per hushåll vid cirka 11 000 km per bil och år (s. 7).</li><li>Högst 25 % bilresor för de boende, Malmö stads mål för stadsdelen (s. 7–9). Med 2,8 resor per person och dag blir det högst 0,7 bilresor (s. 7, not 3).</li><li>Bilpool för cirka 70 % av hushållen och egen bil för högst 30 % (s. 7, not 3).</li></ul></div><div><h3>Det som inte ingår i förvalen</h3><ul class="small as-list"><li>Arbetsplatser, besökare och godstransporter till området.</li><li>Trafik under byggtiden.</li><li>Bilpoolens elektrifiering: ange en högre elbilsandel för de nya hushållens bilar om du vill pröva den.</li><li>Låga hastigheter inom området: Bilmodell v7 räknar hastighet bara för motorleder.</li><li>Etappvis utbyggnad: scenariot visar ett fullt utbyggt område.</li></ul></div></div><h3>Mobilitetsprinciperna i modellen</h3><div class="table-wrap"><table class="as-wrap"><thead><tr><th>Trivector</th><th>Åtgärd i Bilmodell v7</th><th class="numeric">Nivå</th></tr></thead><tbody>'+AS_STRATEGI_TABELL.map(x=>'<tr><td>'+esc(x[0])+'</td><td>'+esc(x[1])+'</td><td class="numeric">'+esc(x[2])+'</td></tr>').join('')+'</tbody></table></div><p class="small">Översättningen är en tolkning gjord i Vägvis, inte Trivectors. Åtgärdernas effekter och osäkerheter är Bilmodell v7:s.</p></article>';}

/* 2.0.6: Scenariot i korthet. Förutsättningar och resultat i ord för vald DeSO, i båda modellerna. */
function asFresh(model){const r=model===activeModel?result:states[model]?.result,dt=model===activeModel?dirty:(states[model]?.dirty??true);if(!r||dt||!AS?.active)return false;return model==='household'?r.metrics?.areaScenario?.deso===AS.deso:(r.config?.areaTraffic||[]).length>0;}
function asPkgName(){const id=AS.measures?.packageId;if(id==='trivector')return 'Mobilitetsstrategi Jägersro, Trivector 2025, tolkning';if(!id||id==='inga'||id==='egna')return null;return ATGd().forval.find(z=>z.id===id)?.namn||null;}
function asMeasureNames(st){return ATGd().lista.filter(m=>st?.[m.id]?.pa).map(m=>m.namn+(m.typ!=='binar'?' ('+num(st[m.id].niva)+' %)':''));}
function asANums(d){const aD=asADeso(AS);if(!aD)return null;const p=asShare(aD),dv=asDeltaV(d),din=dv*p,cA=V.config(aCfg()),fa=V.factors(cA,{},null,true)[0],tc=1+cA.trafficChange,res=aResult(),get=k=>res?.results?.find(y=>y.key===k)?.central||null;return {aD,p,dv,din,fa,dT:din*tc*fa.total/1e6,dD:din*tc*fa.ttw/1e6,xd:get('deso|'+AS.city+'|'+aD.id)};}
function asSummary(x){const d=x.d,as=d.as,r=as.row,b=d.base,s=d.scen,n=d.nu,c=d.prep.c,K=cityName(as.city),u=x.u||HH().areaMC(bProj(),x.c),budget=Number(AS.budget)||AS_BUDGET,ev=asEvNeed(d,budget),A=asANums(d),split=as.mode!=='area'&&n,F=[],R=[],RA=[];
 F.push(r.rs+' (DeSO '+r.kod+') i stadsdelsområdet '+r.sd+', '+K+'. I dag '+num(r.hh)+' hushåll och '+num(r.bef)+' invånare med '+num(r.bph,2)+' bilar per hushåll och '+r7(r.km)+' km per bil (Bilmodell v7, 2023).');
 F.push(as.N>0?num(as.N)+' nya bostäder med '+num(as.persons,Number.isInteger(as.persons)?0:2)+' invånare per bostad, alltså '+num(as.N*as.persons)+' nya invånare.':'Ingen ny bebyggelse.');
 if(as.N>0){if(as.mode==='area')F.push('De nya hushållen får samma bilinnehav och körsträcka som området i dag, med Bilmodell v7:s täthetseffekt för förtätning.');
  else{const so=as.nu.source,from=as.mode==='analog'?'De nya hushållen utgår från '+(so?.kod?(bProj().households.find(h=>h.kod===so.kod)?.rs||so.kod)+' ('+so.kod+')':'stadsdelsområdet '+so?.sd)+': ':'De nya hushållen har egna värden: ';
   F.push(from+num(as.nu.bph0,2)+' bilar per hushåll och '+r7(as.nu.km0)+' km per bil.'+(as.nu.cap>0?' Parkeringstalet '+num(as.nu.cap,2)+' platser per bostad är ett tak för bilinnehavet.':''));
   F.push('Elbilar är '+num(as.nu.el*100,1)+' % och laddhybrider '+num(as.nu.lh*100,1)+' % av de nya hushållens bilar'+(AS.ev?.el!=null||AS.ev?.lh!=null?' (egna värden).':', samma andelar som i '+K+', '+(c.household.shareYear==='egna'?'kommunens egna värden':'år '+c.household.shares[c.household.shareYear].name)+'.'));}}
 const mn=asMeasureNames(as.state),pk=asPkgName();
 F.push(mn.length?'Mobilitetsåtgärder'+(pk?' ('+pk+')':'')+': '+mn.join(', ')+'. '+(as.mode==='area'?'De gäller alla hushåll i DeSO:n.':as.old.apply?'De gäller de nya hushållen och, utom åtgärder för nya bostäder, även de befintliga.':'De gäller de nya hushållen; de befintliga hushållen påverkas inte.'):'Inga mobilitetsåtgärder.');
 if(c.trafficChange||c.electrify)F.push('Dessutom gäller kommunscenariot i modell B: trafikarbetet '+vpct(c.trafficChange)+' och elandelen +'+num(c.electrify*100)+' procentenheter.');
 if(A)F.push('I modell A antas '+num(A.p*100,1)+' % av de boendes bilkörning ske på DeSO:ns vägar'+(AS.a?.share!=null?' (eget värde).':', beräknat ur DeSO:ns yta ('+num(A.aD.km2,2)+' km²) och '+num(AS.a?.tripKm??AS_TRIP_KM)+' km reslängd.'));
 const dD=s.direct-b.direct,dT=s.total-b.total,q=u?.diff,pb=b.direct*1000/b.bef,ps=s.direct*1000/s.bef,verb=v=>Math.abs(v)<.5?'är oförändrade':v>0?'ökar':'minskar';
 R.push('De boendes bilar kör '+num(s.vkm/1e6,1)+' miljoner km per år, mot '+num(b.vkm/1e6,1)+' miljoner i dag ('+vpct(s.vkm/b.vkm-1)+').');
 R.push('De direkta CO₂-utsläppen '+verb(dD)+' från '+r7(b.direct)+' till '+r7(s.direct)+' ton per år ('+asSgn(dD)+' ton'+(q?'; 90 %: '+asSgn(Math.min(q.p5,q.p95))+' till '+asSgn(Math.max(q.p5,q.p95)):'')+'). Med livscykeln '+verb(dT)+' de från '+r7(b.total)+' till '+r7(s.total)+' ton CO₂e.');
 if(as.N>0&&dD>0&&ps<pb)R.push('Ökningen beror på de '+num(as.N*as.persons)+' nya invånarna. Per invånare sjunker snittet i DeSO:n från '+r7(pb)+' till '+r7(ps)+' kg, eftersom de nya hushållen har färre bilar ('+num(split?as.nu.B:s.cars/s.hh,2)+' mot '+num(r.bph,2)+' per hushåll).');
 else if(Math.abs(ps-pb)>=.5)R.push('Per invånare '+(ps<pb?'sjunker':'ökar')+' snittet i DeSO:n från '+r7(pb)+' till '+r7(ps)+' kg per år.');
 if(split&&(as.anyMeasures||as.nu.takBinder))R.push('Åtgärderna'+(as.nu.takBinder?' och parkeringstalet':'')+' ger de nya hushållen '+num(as.nu.B,2)+' bilar per hushåll i stället för '+num(as.nu.bph0,2)+', och '+vpct(as.nu.V/(as.nu.bph0*as.nu.km0)-1)+' fordonskm per hushåll jämfört med utgångsläget.');
 else if(as.mode==='area'&&as.anyMeasures)R.push('Åtgärderna ändrar fordonskm per hushåll med '+vpct(as.area.fV-1)+' och bilinnehavet med '+vpct(as.area.fB-1)+'.');
 if(split&&n.bef>0){const pp=n.direct*1000/n.bef,qp=u?.nu?.perPers;R.push('De nya invånarna står för '+r7(pp)+' kg direkt CO₂ per person och år'+(qp?' (90 %: '+r7(Math.min(qp.p5,qp.p95))+'–'+r7(Math.max(qp.p5,qp.p95))+')':'')+', '+(pp<=budget?'inom':'över')+' budgeten '+num(budget)+' kg.'+(ev&&pp>budget?(ev.evNeed<=1?' Budgeten nås om ungefär '+num(ev.evNeed*100)+' % av körningen är eldriven (nu '+num(ev.evNow*100)+' %), eller om körningen minskar med '+num(ev.cut*100)+' %.':' Budgeten nås inte ens med helt eldriven körning; körningen behöver minska.'):''));}
 let d0=null;try{const c0=V.clone(x.c);delete c0.areaScenario;d0=HH().deterministic(bProj(),c0);}catch(e){}
 if(d0&&Math.abs(dD)>=.5){const eff=s.direct-d0.scenario.get(r.keys[1]).direct,dist=d0.base.get(r.keys[2]),ci=d0.base.get(r.keys[0]);R.push('Det motsvarar '+vpct(eff/dist.direct)+' av de direkta utsläppen från hushållens bilar i stadsdelsområdet '+r.sd+' och '+vpct(eff/ci.direct)+' i '+K+'.');}
 if(A){RA.push('På DeSO:ns vägar '+(A.din>=0?'tillkommer':'försvinner')+' '+num(Math.abs(A.din)/1e6,2)+' miljoner fordonskm per år, '+num(A.p*100,1)+' % av de boendes ändrade körning.');
  RA.push('Livscykelutsläppen från trafiken i DeSO:n '+(A.dT>=0?'ökar':'minskar')+' med '+r7(Math.abs(A.dT))+' ton CO₂e per år'+(A.xd?', från '+r7(A.xd.total)+' till '+r7(A.xd.total+A.dT)+' ton ('+vpct(A.dT/A.xd.total)+')':'')+'. Avgasutsläppen ändras med '+asSgn(A.dD)+' ton CO₂.');
  RA.push('Resten av de boendes körning sker på vägar i andra områden och kommuner och syns inte i DeSO:n. Genomfartstrafik, arbetsplatser, besökare och godstransporter ändras inte.');}
 else RA.push('Modell A finns inte för '+K+'. Scenariot räknas bara i modell B.');
 const mod=activeModel==='household'?'B':'A',fresh=asFresh(activeModel);
 const status=!AS.active?'Förhandsvisning: scenariot ingår inte i beräkningen. Kryssa i Ta med områdesscenariot för att få det i kartan, översikten och exporten.':fresh?'Senaste beräkningen i modell '+mod+' innehåller scenariot. Kartan kan visa scenariot och förändringen.':'Klicka Beräkna med osäkerhet för att få scenariot i kartan, översikten och exporten i modell '+mod+'.';
 return {F,R,RA,status,fresh};}
function asSumLive(x){const S=asSummary(x),li=a=>'<ul class="as-list">'+a.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>';return '<div class="grid2 grid-even as-sum"><div><h3>Förutsättningar</h3>'+li(S.F)+'</div><div><h3>Modell B · de boendes bilar</h3>'+li(S.R)+'<h3>Modell A · trafiken på DeSO:ns vägar</h3>'+li(S.RA)+'</div></div><div class="as-sum-foot"><p class="small"><span class="status '+(S.fresh?'st-ok':AS.active?'st-nara':'st-avvik')+'">'+(S.fresh?'Beräknat':AS.active?'Inte beräknat än':'Förhandsvisning')+'</span> '+esc(S.status)+'</p><div class="button-row"><button type="button" class="secondary small-btn" data-as-map="1">Visa i kartan →</button><button type="button" class="secondary small-btn" id="as-sum-dl">Ladda ner sammanfattningen (.txt)</button></div></div>';}
function asSumText(){const x=asDetail();if(x.error)return x.error;x.u=HH().areaMC(bProj(),x.c);const S=asSummary(x),d=x.d,b=d.base,s=d.scen,L=[];
 L.push('Vägvis '+V.VERSION+' · Områdesscenario','Datum: '+new Date().toISOString().slice(0,10),'Område: '+d.as.row.rs+' (DeSO '+d.as.deso+'), '+d.as.row.sd+', '+cityName(d.as.city),'Förval: '+(AS_PRESETS[AS.presetId]?.namn||'Eget scenario'),'','FÖRUTSÄTTNINGAR',...S.F.map(t=>'- '+t),'','RESULTAT, MODELL B (de boendes bilar)',...S.R.map(t=>'- '+t),'','RESULTAT, MODELL A (trafiken på DeSO:ns vägar)',...S.RA.map(t=>'- '+t),'','TABELL FÖR DeSO:N (centrala värden)','Mått;I dag;Scenario;Förändring');
 const n0=v=>String(Math.round(v)),n2=v=>v.toFixed(2).replace('.',','),row=(l,f,dec)=>L.push(l+';'+dec(f(b))+';'+dec(f(s))+';'+dec(f(s)-f(b)));
 row('Hushåll',z=>z.hh,n0);row('Invånare',z=>z.bef,n0);row('Bilar',z=>z.cars,n0);row('Bilar per hushåll',z=>z.cars/z.hh,n2);row('Fordonskm per år',z=>z.vkm,n0);row('Direkt CO2, ton per år',z=>z.direct,n0);row('Livscykel, ton CO2e per år',z=>z.total,n0);row('Direkt CO2 per invånare, kg',z=>z.direct*1000/z.bef,n0);
 L.push('','Direkt CO2 räknas som i Bilmodell v7 (fliken Klimatpåverkan). Intervallen är 90 %.','Status: '+S.status);return L.join('\r\n');}
