function areaRows(){const v=x=>mapShow==='diff'?(x.central&&x.scenarioCentral?x.scenarioCentral.total-x.central.total:null):aVal(x,mapShow==='scenario'?'scenarioCentral':'central');return (result?.results||[]).filter(x=>x.city===currentCity&&x.level===currentLevel).sort((a,b)=>(v(b)??-1e18)-(v(a)??-1e18));}
function mapView(){const areas=project.areas.filter(a=>a.city===currentCity&&a.level===currentLevel),leg=mapShow==='diff'?'<div class="map-key class-legend"><span>Förändring av ton CO₂e per år mot basfallet (samma procent totalt och per hektar)</span>'+diffLegend()+'</div>':'<div class="map-key"><span>'+(aMeasure==='ha'?'Lägre utsläpp per hektar landyta':'Lägre totalt utsläpp')+'</span><span class="gradient"></span><span>Högre</span><span>Grått: underlag saknas</span>'+(mapShow==='scenario'?'<span>Samma skala som basfallet</span>':'')+'</div>';return notice()+'<div class="row wrap">'+tabs()+aMeasureToggle()+mapToggle()+'</div>'+mapNote()+'<article class="card"><div class="row"><div><h2>'+esc(currentLevel==='deso'?'DeSO · '+(project.metadata.desoVersion||cfg.desoVersion):'Stadsdelsområden · importerad kommunindelning')+(mapShow==='scenario'?' · scenario':mapShow==='diff'?' · förändring':'')+'</h2><p class="card-sub">'+(mapShow==='base'?(aMeasure==='ha'?'Ton CO₂e per hektar landyta och år.':'Huvudresultat i ton CO₂e/år.'):mapWhat()+(aMeasure==='ha'&&mapShow==='scenario'?' Per hektar landyta.':''))+' Klicka på ett område för mer information.</p></div></div>'+(areas.length?'<div class="map-layout"><div><div class="map-toolbar"><label><input id="map-osm" type="checkbox" checked> OpenStreetMap</label><label><input id="map-roads" type="checkbox"> Väglänkar</label><button class="secondary" id="map-fit">Visa hela kommunen</button></div><div class="map-surface" id="map-surface" role="region" aria-label="Karta med områdesresultat"></div><p class="small" id="map-status" role="status"></p>'+leg+'</div><aside id="area-detail" class="area-detail"><span class="tagline">UTFORSKA ETT OMRÅDE</span><h3>Klicka i kartan</h3><p class="small">'+(activeModel==='household'?'Resultatet avser hushållens bilar, även när de kör utanför hemområdet.':'Resultatet avser trafiken på vägarna här, även besökare och genomfart.')+'</p></aside></div>':'<div class="empty"><span class="empty-icon">⌁</span><strong>Områdesgränser saknas</strong>Referensfallet kan inte fördelas till verkliga områden utan kart- och trafikunderlag.<br><button class="secondary" data-go="data">Hämta eller importera underlag →</button></div>')+'</article><article class="card" style="margin-top:18px"><div class="table-tools"><h2 style="margin:0;min-width:120px">Alla områden</h2><input class="input" id="area-search" type="search" placeholder="Sök namn eller områdeskod" aria-label="Sök område"><button class="secondary" id="area-csv">Exportera denna nivå</button></div><div class="table-wrap"><table><thead><tr><th>Område</th><th>Kod</th><th class="numeric">Basfall · ton</th><th class="numeric">Ton/ha</th><th class="numeric">P2,5</th><th class="numeric">P97,5</th><th class="numeric">Scenario · ton</th><th class="numeric">Förändring</th><th class="numeric">Fordonskm</th><th class="numeric">Landyta, ha</th></tr></thead><tbody id="area-table">'+tableRows()+'</tbody></table></div><p class="small">Tomma värden betyder att beräkningsunderlag saknas. De ska inte läsas som nollutsläpp. Ton/ha avser landytan (DeSO-gränsen klippt mot land). Kommunen inkluderar även eventuella ej områdesfördelade poster. Scenariot avser senaste beräkningen.</p></article>';}
function tableRows(search=''){if(activeModel==='household')return householdTableRows(search);const rows=areaRows().filter(x=>(x.name+' '+x.id).toLocaleLowerCase('sv').includes(search.toLocaleLowerCase('sv')));return rows.length?rows.map(x=>{const ya=areaHa(x),d=x.central&&x.scenarioCentral?x.scenarioCentral.total-x.central.total:null;return '<tr data-select-area="'+esc(x.key)+'"><td>'+esc(x.name)+'</td><td>'+esc(x.id)+'</td><td class="numeric">'+num(x.central?.total)+'</td><td class="numeric">'+fmtHa(perHa(x.central?.total,ya))+'</td><td class="numeric">'+num(x.base?.p025)+'</td><td class="numeric">'+num(x.base?.p975)+'</td><td class="numeric">'+num(x.scenarioCentral?.total)+'</td><td class="numeric">'+(d==null?'—':Math.abs(d)<.5?'0':asSgn(d,v=>num(v))+' ('+vpct(d/x.central.total)+')')+'</td><td class="numeric">'+num(x.central?.vkm)+'</td><td class="numeric">'+(ya?num(ya.landHa,ya.landHa>=100?0:1):'—')+'</td></tr>';}).join(''):'<tr><td colspan="10">Inga områdesresultat att visa.</td></tr>';}
function drawMap(){if(!$('map-surface'))return;const idx=Object.fromEntries((result?.results||[]).filter(x=>x.city===currentCity&&x.level===currentLevel).map(x=>[x.id,x]));if(activeModel==='household'){const sn=hMean(currentLevel),ap=new Set(project.areas.filter(a=>a.city===currentCity&&a.level===currentLevel&&a.approximate).map(a=>a.id));window.VagvisMaps.draw({project,city:currentCity,level:currentLevel,result,onSelect:id=>showArea(currentLevel+'|'+currentCity+'|'+id),fill:id=>hColor(idx[id],sn),tooltip:id=>idx[id]?hTooltip(idx[id]):'Underlag saknas',dashed:id=>ap.has(id),fillOpacity:.82,attribution:'Områden: SCB, klippta mot land i Bilmodell v7'});}else{const max=aMax(),names=Object.fromEntries(project.areas.filter(a=>a.city===currentCity&&a.level===currentLevel).map(a=>[a.id,a.name||a.id]));window.VagvisMaps.draw({project,city:currentCity,level:currentLevel,result,onSelect:id=>showArea(currentLevel+'|'+currentCity+'|'+id),fill:id=>aFill(idx[id],max),tooltip:id=>aTooltip(idx[id],names[id])});}
 /* Valt område följer med när kartan ritas om; med ett aktivt områdesscenario väljs dess DeSO. */
 const sel=selectedArea&&idx[selectedArea]?selectedArea:asMapId();if(sel&&idx[sel])showArea(currentLevel+'|'+currentCity+'|'+sel);}
function showArea(key){const x=result?.results.find(x=>x.key===key),panel=$('area-detail');if(!x||!panel)return;selectedArea=x.id;window.VagvisMaps.select(x.id);document.querySelectorAll('#map-svg path').forEach(p=>p.classList.toggle('selected',p.dataset.area===x.id));if(activeModel==='household'){panel.innerHTML=householdArea(x);return;}const ya=areaHa(x);panel.innerHTML='<span class="tagline">'+esc(x.id)+'</span><h3>'+esc(x.name)+'</h3><div class="duo"><div><div class="big">'+num(x.central?.total)+'</div><span>ton CO₂e/år · totalt</span></div><div><div class="big">'+fmtHa(perHa(x.central?.total,ya))+'</div><span>ton CO₂e/ha · per hektar landyta</span></div></div>'+(x.central&&x.scenarioCentral&&Math.abs(x.scenarioCentral.total-x.central.total)>1e-9*x.central.total?'<p class="as-value" style="margin-top:-8px">Scenario: '+num(x.scenarioCentral.total)+' ton ('+vpct(x.scenarioCentral.total/x.central.total-1)+') · '+fmtHa(perHa(x.scenarioCentral.total,ya))+' ton/ha</p>':'')+'<dl><dt>95 % modellintervall</dt><dd>'+num(x.base?.p025)+'–'+num(x.base?.p975)+' ton</dd><dt>Scenario</dt><dd>'+num(x.scenarioCentral?.total)+' ton</dd>'+(x.central&&x.scenarioCentral&&Math.abs(x.scenarioCentral.total-x.central.total)>1e-9*x.central.total?'<dt>Förändring</dt><dd>'+asSgn(x.scenarioCentral.total-x.central.total,v=>num(v))+' ton ('+vpct(x.scenarioCentral.total/x.central.total-1)+')</dd><dt>95 % för förändringen</dt><dd>'+num(x.difference?.p025)+' till '+num(x.difference?.p975)+' ton</dd>':'')+'<dt>Landyta</dt><dd>'+haTxt(ya?.landHa)+(ya&&ya.ha-ya.landHa>=1?' (och '+haTxt(ya.ha-ya.landHa)+' vatten inom beräkningsgränsen)':'')+'</dd><dt>95 % per hektar</dt><dd>'+fmtHa(perHa(x.base?.p025,ya))+'–'+fmtHa(perHa(x.base?.p975,ya))+' ton CO₂e/ha</dd><dt>Trafikarbete</dt><dd>'+num(x.central?.vkm)+' fordonskm</dd><dt>Direktutsläpp</dt><dd>'+num(x.central?.ttw)+' ton CO₂e</dd><dt>Gränsversion</dt><dd>'+esc(x.version||'ej angiven')+'</dd></dl><p class="small">'+(x.central?''+(activeModel==='household'?'Osäkerheten innehåller gemensamma kommun- och teknikfaktorer.':'Osäkerheten innehåller gemensamma stads- och vägklassfaktorer.')+'':'Området saknar beräkningsunderlag. Resultatet är okänt.')+'</p>'+'<div class="button-row">'+calcButton(x.key)+(x.level==='deso'?(()=>{try{const r=asBForA(x);return r?asOpenButton(r.kk,r.kod):'';}catch(err){return '';}})():'')+'</div>';}
function field(label,key,value,note,attr=''){return '<div class="field"><label for="cfg-'+key+'">'+label+'</label><input class="input" id="cfg-'+key+'" data-cfg="'+key+'" type="number" value="'+value+'" '+attr+'><small>'+note+'</small></div>';}
function parametersAssumptions(){if(activeModel==='household')return householdParameters();const fuelNames={petrol:'Bensin',diesel:'Diesel',bev:'El',phev:'Laddhybrid',biogas:'Biogas',hvo:'HVO'},uLabels={city:'Gemensamt aktivitetsfel, stad',class:'Gemensamt fel per vägklass',localAssumed:'Schablontrafik, lokal cell',localMeasured:'Mätt trafik, lokal cell',spatial:'Gemensam geografisk fördelning',energy:'Energianvändning',production:'Fordon och batteriproduktion',life:'Livslängd',electricity:'Elens klimatfaktor',upstream:'Drivmedlens tidigare led',reference:'Kommunalt referensvärde'};return '<div class="notice info"><strong>Kalibreringen utgår från basfallet.</strong> Scenarioändringar i trafikmängd och elandel ändrar utsläppen utan att kalibreras tillbaka till kommunens gamla utsläpp. Beräkningsåret väljer kalenderlängd och referensmatchning; det skapar inte automatiskt en ny fordonsflotta eller bränslemix.</div><article class="card"><h2>Pröva ett scenario</h2><p class="card-sub">Förändring mot basfallet, lika för alla inlästa områden och fordonsklasser.</p><div class="controls"><div class="field"><label for="traffic-range">Trafikarbete <span class="range-output" id="traffic-output">'+num(cfg.trafficChange*100)+' %</span></label><input id="traffic-range" data-range="trafficChange" type="range" min="-80" max="100" step="1" value="'+cfg.trafficChange*100+'"><small>Fordonskilometer. Ingen automatisk omfördelning mellan vägar eller färdsätt.</small></div><div class="field"><label for="ev-range">Ökad elandel <span class="range-output" id="ev-output">'+num(cfg.electrify*100)+' procentenheter</span></label><input id="ev-range" data-range="electrify" type="range" min="0" max="100" step="1" value="'+cfg.electrify*100+'"><small>Flyttar kilometer från övriga drivlinor till el, högst till 100 %.</small></div><div class="field"><label for="mode">Beräkningssätt</label><select id="mode" data-cfg="mode"><option value="calibrated" '+(cfg.mode==='calibrated'?'selected':'')+'>Kalibrera basfall mot kommunreferens</option><option value="network" '+(cfg.mode==='network'?'selected':'')+'>Beräkna direkt från vägnätets trafik</option></select><small>Kalibrering används endast där referensvärde och år matchar. Helsingborg saknar förifylld referens. Gävle kalibreras mot en framskriven referens ur Nationella emissionsdatabasen.</small></div></div></article>'+areaScenarioCard()+'<article class="card" style="margin-top:18px"><h2>Gemensamma beräkningsval</h2><div class="controls">'+field('Kalenderår','year',cfg.year,'2024 har 366 dygn. Ändrat år kräver också relevanta indata.','min="2000" max="2100" step="1"')+field('El · g CO₂e/kWh','electricity',cfg.electricity,'37 är en referens för svensk elmix från Boverket; inte uppmätt SE4-laddning 2024.','min="0" max="2000" step="1"')+field('Batteriproduktion · kg CO₂e/kWh','batteryEF',cfg.batteryEF,'Utvecklingsantagande. Batteriet läggs till utöver kaross och drivlina.','min="0" max="1000" step="1"')+field('Laddverkningsgrad · andel','chargeEfficiency',cfg.chargeEfficiency,'Förbrukningen i fordonsfliken avser energi till fordonet. Laddförluster tillkommer här.','min="0.1" max="1" step="0.01"')+field('Laddhybrid: körsträcka på el · andel','phevElectric',cfg.phevElectric,'Använd verklig användning, inte enbart typgodkännande.','min="0" max="1" step="0.01"')+field('Monte Carlo · antal simuleringar','iterations',cfg.iterations,'3 000 är standard. Fler dragningar förbättrar numerisk precision, inte datakvaliteten.','min="100" max="30000" step="100"')+field('Slumptalsfrö','seed',cfg.seed,'Samma frö och oförändrade data ger samma simulering.','min="0" max="4294967295" step="1"')+'</div></article><details class="card"><summary>Fordon: förbrukning, produktion och livslängd</summary><p class="small">Alla värden i denna tabell är justerbara utvecklingsantaganden för en genomsnittlig fordonsklass. Kaross/drivlina avser ett fordon utan separat traktionsbatteri. Modellens lilla drivlinepåslag är 5 % för el och 8 % för laddhybrid.</p><div class="table-wrap"><table><thead><tr><th>Fordon</th><th>Livslängd km</th><th>Kaross kg CO₂e</th><th>Batteri kWh</th><th>Bränsle MJ/km</th><th>El kWh/km</th><th>Underhåll g/km</th><th>Slut kg CO₂e</th><th>Kredit kg CO₂e</th><th>Övrig TTW g/km</th></tr></thead><tbody>'+cfg.profiles.map((p,i)=>'<tr><td>'+esc(p.name)+'</td>'+['life','body','battery','mj','kwh','maint','eol','credit','other'].map(k=>'<td><input class="input-small" data-profile="'+i+'" data-key="'+k+'" type="number" min="0" step="any" value="'+p[k]+'" aria-label="'+esc(p.name+' '+k)+'"></td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="small">MJ/km används för respektive förbränningsdrivlina; ett förenklat gemensamt antagande inom klassen. Underhåll inkluderar däck och reservdelar, inte vägen. Övrig TTW avser schablon för CH₄ och N₂O uttryckt som CO₂e.</p></details><details class="card"><summary>Fordonsmix: andel av körda kilometer</summary><p class="small">Inte andel av registrerade fordon. Inkludera besökare, genomfart och utlandsregistrerade fordon. Varje rad ska summera till 100 %.</p><div class="table-wrap"><table class="mix-table"><thead><tr><th>Fordon</th>'+Object.values(fuelNames).map(x=>'<th>'+x+' %</th>').join('')+'<th>Summa %</th></tr></thead><tbody>'+cfg.profiles.map((p,i)=>'<tr><td>'+esc(p.name)+'</td>'+Object.keys(fuelNames).map(k=>'<td><input class="input-small" data-mix="'+i+'" data-key="'+k+'" type="number" min="0" max="100" step="0.1" value="'+((p.mix[k]||0)*100).toFixed(2)+'" aria-label="'+esc(p.name+' '+fuelNames[k])+'"></td>').join('')+'<td id="mixsum-'+i+'">'+num(Object.values(p.mix).reduce((a,b)=>a+b,0)*100,2)+'</td></tr>').join('')+'</tbody></table></div></details><details class="card"><summary>Bränslen: fysisk fossilandel och tidigare led</summary><p class="small">Fossil energiandel är ett antagande. Reduktionsplikt är inte samma mått. EU:s fossila komponentvärden är referensfaktorer; byt till dokumenterade bränsle- och årsdata där de finns.</p><div class="table-wrap"><table><thead><tr><th>Bränsle</th><th>Fossil energiandel %</th><th>Fossil TTW g/MJ</th><th>Fossil tidigare led g/MJ</th><th>Biokomponent tidigare led g/MJ</th><th>Biogen CO₂ g/MJ</th></tr></thead><tbody>'+Object.entries(cfg.fuels).map(([id,f])=>'<tr><td>'+esc(f.name)+'</td>'+['fossil','ttw','wtt','bio','bioCO2'].map(k=>'<td><input class="input-small" type="number" min="0" step="any" data-fuel="'+id+'" data-key="'+k+'" value="'+(k==='fossil'?f[k]*100:f[k])+'" aria-label="'+esc(f.name+' '+k)+'"></td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="small">Biokomponenternas faktorer ska omfatta odling/produktion, transport och bränslekedjans utsläpp. Eventuell markanvändningsförändring måste finnas i valda faktorer; ingen extra markmodul beräknas.</p></details><details class="card"><summary>Osäkerhet: antagna variationskoefficienter</summary><p class="small">CV = standardavvikelse / medelvärde. Ange andelar, exempelvis 0,20 = 20 %. Positiva faktorer samplas lognormalt med medelvärde 1. Alla CV-värden nedan är antagna, inte empiriskt skattade.</p><div class="controls">'+Object.entries(uLabels).map(([k,label])=>'<div class="field"><label>'+label+'</label><input class="input" type="number" min="0" max="3" step="0.01" data-uncertainty="'+k+'" value="'+cfg.uncertainty[k]+'"></div>').join('')+'<div class="field"><label>Fordonsmix: Dirichlet-koncentration</label><input class="input" type="number" min="1" max="100000" step="1" data-uncertainty="mixConcentration" value="'+cfg.uncertainty.mixConcentration+'"><small>Större värde innebär mindre osäkerhet i drivlinornas andelar.</small></div></div></details>'+(city()?.reference?'<article class="card"><h2>Separat trafikarbete för buss</h2><p class="small">Noll i kommunens direkta utsläppstabell innebär inte att busstrafiken saknar livscykelutsläpp.</p><div class="field" style="max-width:400px"><label>Busskilometer i kommunen per år</label><input class="input" id="bus-vkm" type="number" min="0" step="100000" value="'+city().reference.busVkm+'"><small>18 miljoner i startfallet är ett utvecklingsantagande, inte verifierad Malmöstatistik. I nätläget hämtas busskilometer från länkarnas bussandel.</small></div></article>':'')+'<div class="form-note">Ingen automatisk beräkning av köbildning, kallstarter, tomgång, temperatur eller lutning i version 1.0. Deras genomsnittliga effekt behöver inkluderas i inlagd förbrukning. Vägbyggande och vägunderhåll ingår enligt vald systemgräns inte.</div>';}
function dataView(){if(activeModel==='household')return householdData();return notice()+'<article class="card" style="margin-bottom:18px"><h2>Från mätning till trafikarbete</h2><p>Varje väglänk räknas som längd inom området × ÅDT × kalenderdygn × fordonsandel. År 2024 har 366 dygn. Startprojektet har OSM-vägnätet för Malmö och Helsingborg (dataläge 20 oktober 2026) och Gävle (dataläge 2026-05-31) med schablon-ÅDT per vägklass. Uppmätt trafik saknas fortfarande. I kalibrerat läge skalas Malmös trafik till kommunens referens för 2024; Helsingborg saknar referens och räknas direkt på nätet. Gävle skalas till en referens ur Nationella emissionsdatabasen (2022, framskriven till 2024), eftersom schablonerna annars ger dubbelt så höga utsläpp på landsbygdens vägar.</p><p class="small">MVD kräver mvdToAadtFactor, conversionSource och conversionCV. Ett annat mätår kräver yearFactor med källa och CV. För båda riktningarna på en enskild körbana krävs en dokumenterad riktningsandel. Rådata och omräkningar sparas i projektet. Omräkningsfel med samma grupp dras gemensamt.</p><p><a href="Trafikdata_till_Malmo.html" target="_blank" rel="noopener">Öppna färdig dataförfrågan till Malmö stad ↗</a></p><p class="small">Vid vägnätsimport väljs direkt nätberäkning automatiskt, så att mätningarna inte skalas till kommunens referensvärde.</p></article>'+ '<div class="grid2"><article class="card"><h2>Vägnätet är inläst – komplettera med uppmätt trafik</h2><div class="steps"><div class="step"><div><strong>Hämta öppna underlag</strong><p>DeSO-filerna, v7-grupperingarna och OSM-vägnätet (dataläge 20 oktober 2026) är redan inlästa. Hämtningen behåller dem och kompletterar bara det som saknas. Vill du byta till ett nyare vägnät: ladda ner det med direktlänken och läs in det med Importera vägnät. OSM-trafikmängder är schabloner. Hämtningen körs i din webbläsare, i mindre rutor mot tre Overpass-servrar, och tar några minuter.</p><div class="button-row"><button class="primary" id="fetch-open">Hämta öppna underlag</button><select id="deso-version" aria-label="DeSO-version"><option value="2018" '+(cfg.desoVersion==='2018'?'selected':'')+'>DeSO 2018 · för 2024</option><option value="2025" '+(cfg.desoVersion==='2025'?'selected':'')+'>DeSO 2025</option></select></div>'+osmLankar()+'</div></div><div class="step"><div><strong>Förbättra med kommunens trafikmodell</strong><p>Importera ett ÅDT-satt vägnät i GeoJSON WGS84. Trafiken ska avse varje linjegeometri och omfatta hela året. Behåll schabloner där mätdata saknas, med tydlig märkning.</p><div class="button-row"><button class="secondary" data-import="roads">Importera vägnät</button><button class="secondary" data-import="deso">Importera DeSO</button><button class="secondary" data-import="district">Importera stadsdelsområden</button></div></div></div><div class="step"><div><strong>Beräkna och spara ditt projekt</strong><p>Beräkna osäkerheten, kontrollera områdestäckningen och spara en projektfil eller egen offlinekopia. Därefter behövs varken internet eller Netlify för att köra modellen.</p><button class="secondary" id="save-data-project">Spara komplett projekt</button></div></div></div></article><article class="card"><h2>Import och kontroll</h2><p class="card-sub">All bearbetning av importerade filer sker i din webbläsare.</p><div class="button-row"><button class="primary" data-import="project">Öppna sparat projekt</button><button class="secondary" id="load-demo">Visa fiktivt räkneexempel</button><button class="secondary" id="reset-reference">Återställ referensfall</button></div><div class="coverage" style="grid-template-columns:1fr 1fr;margin-top:24px"><div class="stat"><b>'+num(project.areas.length)+'</b><span>områdesgeometrier totalt</span></div><div class="stat"><b>'+num(project.roads.length)+'</b><span>väglänkar totalt</span></div></div><p class="small"><strong>Projekt:</strong> '+esc(project.title)+'</p><p class="small">'+esc((project.metadata.notes||[]).join(' '))+'</p><div id="fetch-log" class="log" '+(project.metadata.downloaded?'':'hidden')+'>'+esc((project.metadata.notes||[]).slice(-8).join('\n'))+'</div><p class="small">Vissa datatjänster blockerar hämtning från lokala HTML-filer eller begränsar stora anrop. Använd då det medföljande <strong>Hämta_underlag_windows.cmd</strong> eller ladda ner GeoJSON från källans portal och importera filen. Skriptet kräver Python, själva modellen gör det inte.</p><p class="small">En automatiskt hämtad kartfil är inte en färdig trafikmodell för 2024. Års- och mätmatchning måste granskas.</p></article></div><article class="card"><h2>Hur ska en GeoJSON-fil se ut?</h2><p class="small">Använd koordinatsystem WGS84 / EPSG:4326, longitud först. Vid separat import används vald kommun i sidhuvudet om egenskapen <code>city</code> saknas.</p><div class="table-wrap"><table><thead><tr><th>Typ</th><th>Geometri</th><th>Egenskaper</th><th>Viktig definition</th></tr></thead><tbody><tr><td>DeSO / stadsdelsområde</td><td>Polygon / MultiPolygon</td><td>id, name, city, version</td><td>Unika ID. Ingen blandning av gränsversioner.</td></tr><tr><td>Väg</td><td>LineString / MultiLineString</td><td>id, city, roadClass, aadt, heavyShare, busShare, year</td><td>ÅDT för just den linjen; andelar 0–1.</td></tr><tr><td>Trafikens kvalitet</td><td>Vägens egenskaper</td><td>quality, source, aadtCV</td><td>quality = measured, modelled, imported eller assumed. Utan aadt används schablon. Utan kvalitetsmärkning räknas ett importerat flöde inte som uppmätt.</td></tr><tr><td>Direkt fordonsfördelning</td><td>Vägens egenskaper</td><td>classShares: car, van, rigid, artic, bus, mc, moped</td><td>Valfritt; alla sju andelar ska summera till 1.</td></tr></tbody></table></div><p class="small"><strong>heavyShare avser tunga lastbilar exklusive bussar.</strong> Om källans andel tung trafik inkluderar bussar måste bussandelen först särredovisas. Vardagsdygn är inte samma sak som ÅDT. För två separata körbanor får en gemensam dubbelriktad ÅDT inte läggas på båda. classShares ska avse årsmedeltrafik; MVD-andelar kan behöva klassvis årsprofil innan de används.</p><div class="button-row"><button class="secondary" id="download-template">Ladda ner komplett fiktiv importmall</button><button class="secondary" id="download-road-template">Ladda ner väglänksmall</button></div></article><article class="card" style="margin-top:18px"><h2>Schabloner för länkar utan trafikmängd</h2><p class="small">Utvecklingsantaganden per dubbelriktad väggeometri. För enkelriktad geometri halveras schablon-ÅDT. På ramper används dessutom faktor 0,35. Dessa schabloner ska inte uppfattas som uppmätta lokala trafikmängder.</p><div class="table-wrap"><table><thead><tr><th>Vägklass</th><th>Schablon-ÅDT</th><th>Tung lastbil exkl buss %</th><th>Buss %</th></tr></thead><tbody>'+Object.entries(V.ROAD_DEFAULTS).map(([k,x])=>'<tr><td>'+esc(k)+'</td><td>'+num(x.aadt)+'</td><td>'+num(x.heavy*100,1)+'</td><td>'+num(x.bus*100,1)+'</td></tr>').join('')+'</tbody></table></div><p class="small">Återstående lätt trafik fördelas som antagande: personbil 87 %, lätt lastbil 11 %, motorcykel 1,5 %, moped 0,5 %. Tunga lastbilar fördelas 60/40 utan/med släp. Använd classShares för lokala uppgifter.</p></article>'+warningsHTML();}
const METHOD=`<article class="card"><h2>Två modeller i Vägvis 2.0.8</h2><p><strong>A – trafik inom området:</strong> vägsträcka inom området × ÅDT × kalenderdygn × fordonsfördelning × LCA per fordonskm. Genomfart ingår. Startprojektet har OSM-vägnätet med schablon-ÅDT per vägklass, inte uppmätt länktrafik. I kalibrerat läge skalas Malmös trafik per fordonsgrupp till kommunreferensen 2024 och Gävles till en framskriven referens; Helsingborg räknas direkt på nätet. Gävle (2.0.8) har 55 DeSO 2025 från SCB och 9 stadsdelsområden grupperade som i Bilmodell v7.</p><p><strong>B – hushållens bilar (Malmö, Helsingborg och Gävle):</strong> hushåll × modellerade bilar per hushåll × km per bil. All körning hänförs till hemområdet, även utanför kommunen. Direkt CO₂ räknas exakt som fliken Klimatpåverkan i Bilmodell v7: fordonskm × ((1 − elandel) × 0,15 + elandel × 0,02) kg CO₂ per km, där elandel = elbilar + 40 % av laddhybriderna. Livscykeln är det värdet plus bränslets tidigare led (i proportion till avgasutsläppen), fordons- och batteritillverkning, underhåll och slutbehandling med samma LCA-formler som A. Aktivitetsdata från Bilmodell v7: år 2023, DeSO 2018. A visar DeSO 2025_v2.</p><p><strong>Åtgärder (2.0.4):</strong> mobilitetsåtgärder, förtätning, samverkansregler och referenskontroll räknas med Bilmodell v7:s egen kod (atgarder.js, mc.js och ordagranna utdrag ur app.js, klimat.js och kontroll.js). Åtgärderna påverkar fordonskm per hushåll och, för hastighet och körsätt, utsläppen per km i scenariot. Basfallet påverkas inte. I A kan scenariot ändra trafiken per DeSO eller stadsdelsområde och lägga till nya vägar med en vägtyps schablon-ÅDT; även där är basfallet oförändrat.</p><p><strong>Områdesscenario (2.0.5):</strong> under Antaganden & scenario väljs en DeSO (alla 326 DeSO i Bilmodell v7) och en ny bebyggelse med mobilitetsåtgärder. I B räknas de nya hushållen antingen som området i dag (v7:s flik Befintliga områden), som ett annat befintligt område eller med egna värden (v7:s flik Nya områden, med parkeringstal som tak för bilar per hushåll). Åtgärderna räknas med v7:s kod, och de nya hushållens bilpark kan få egna elbilsandelar. I A blir de boendes ändrade bilkörning en egen rad med personbilstrafik i DeSO:n, bara i scenariot: ändringen i fordonskm från B gånger andelen av körningen som sker inom DeSO:n (standard 1,1 × √(yta/π) / 25 km). Raden kalibreras inte och dras i scenariots egen slumpström. Genomfart, arbetsplatser, besökare och godstransporter ändras inte. Förvalen för Jägersro bygger på Trivectors mobilitetsstrategi (rapport 2025:55); översättningen till v7:s åtgärder är Vägvis tolkning.</p><p><strong>Scenariot i kartan (2.0.6):</strong> efter en beräkning kan kartan visa basfall, scenario eller förändring. Förändringen färgas i procent av basfallet (grönt minskar, grått oförändrat inom ±1 %, orange och rött ökar). Tabellen och områdespanelen följer samma val. Kortet Scenariot i korthet beskriver förutsättningar och resultat för områdesscenariot i ord.</p><p><strong>Gävle i modell A (2.0.8):</strong> 55 DeSO 2025 (SCB) och OSM-vägnätet (9951 länkar, dataläge 2026-05-31) med schablon-ÅDT per vägklass. I kalibrerat läge skalas Gävles trafik, som Malmös, till en referens för 2024: Nationella emissionsdatabasens utsläpp per invånare 2022 (2030-sekretariatet) gånger antalet invånare, framskrivet med rikets förändring per fordonsslag 2022–2024 (Trafikverket). Det ger 132 kton för lätt trafik och 45 kton för tunga lastbilar. Utan kalibrering ger schablon-ÅDT cirka 2,1 gånger så höga direktutsläpp, främst på landsbygdens större vägar. Samma framskrivning ger för Malmö 13 % lägre utsläpp än kommunens egen redovisning, så referensen har en osäkerhet i storleksordningen 15–20 %. De 9 stadsdelsområdena är Bilmodell v7:s, där varje DeSO 2025 hör till det stadsdelsområde den överlappar mest. Gävle har en egen slumpström, så att Malmös och Helsingborgs resultat och intervall är exakt desamma som före tillägget.</p><p><strong>Per hektar och räkneexempel (2.0.7):</strong> kartan och områdespanelen visar både totalen och utsläppen per hektar. I A delas med landytan: DeSO-gränsen klippt mot Bilmodell v7:s landmask, räknad i SWEREF 99 TM (trafiken på broar ingår i totalen, men vattnet räknas inte som yta). I B delas med v7:s landklippta DeSO-yta. Fliken Så räknas resultatet räknar om valt område steg för steg ur samma beräkning som kartan, visar hur varje schablon har tagits fram och med vilken källa, och jämför modellen med oberoende uppgifter. Summan i räkneexemplet kontrolleras automatiskt mot kartans värde för alla områden.</p><p>De båda resultaten överlappar och ska inte summeras. Osäkerheten i B använder Bilmodell v7:s fördelningar för utsläppsfaktorer, eldrift och fordonskm. Vägvis redovisar 95 % modellintervall; för direkt CO₂ i hela kommunen visas även Bilmodell v7:s eget 90-procentsintervall, räknat med v7:s egen kod.</p><p>Landmasken är en ren visningsklippning, härledd från de bifogade v7-ytorna. Analysens administrativa DeSO-gränser är oförändrade, så att vägar och broar i kommunens vatten kan räknas. Kustmaskens detaljer har inte verifierats mot en ny officiell kustlinje. OpenStreetMap visas som nätbaserad bakgrund med licensangivelse; beräkningen och områdeskartan fungerar utan bakgrund.</p><p><a href="Trafikdata_till_Malmo.html" target="_blank" rel="noopener">Dataförfrågan till trafikexperterna</a> · <a href="Bilmodell_v7/index.html" target="_blank" rel="noopener">Bifogad v7 med åtgärdspaket</a></p></article><article class="card method-text"><h2>Vad beräknas?</h2><p>Vägvis beräknar ett klimatavtryck för vägtrafikarbetet inom en geografisk gräns. Funktionell enhet är ett års trafik, redovisat i ton CO₂e per DeSO, stadsdelsområde eller kommun. Varje fordonskilometer räknas där fordonet färdas, oavsett vem som äger fordonet, var resan startar eller vem som efterfrågar transporten. Interna resor, in- och utpendling, besök och genomfart ingår till den del de körs inom området.</p><p><strong>Detta är territoriell trafik med ett livscykeltillägg.</strong> Fordonstillverkning och bränsleproduktion sker ofta på andra platser. De utsläppen allokeras till den körda kilometern; modellen påstår inte att de fysiskt sker i området. Resultatet är inte ett mått på de boendes resvanor eller konsumtionsutsläpp.</p><h2>Systemgräns: fordon och energi</h2><p>Huvudresultatet omfattar direktutsläpp, bränsle- och elproduktion, fordons- och batteriproduktion, fordonsunderhåll och slutbehandling. Sju fordonsklasser ingår: personbil, lätt lastbil, tung lastbil utan släp, tung lastbil med släp, buss, motorcykel och moped. Vägbyggande, vägunderhåll och laddinfrastruktur ingår inte. Arbetsmaskiner, färjor, tåg, cyklar och elsparkcyklar ligger utanför vägfordonsmodulen.</p><p>Med ”cradle to cradle” avses här en bred livscykel med synlig återvinning, inte en certifiering eller ett bevisat slutet materialkretslopp. Slutbehandlingens utsläpp ingår i huvudresultatet. En möjlig kredit för undviken primärproduktion redovisas separat. Att dra av den kräver en dokumenterad systemutvidgning eller allokeringsregel så att samma återvinningsnytta inte krediteras både säljare och köpare. Ingen sådan nettning görs automatiskt.</p><h2>Från trafik till utsläpp</h2><div class="formula">E<sub>område</sub> = Σ fordonskm × (TTW + WTT + fordon + batteri + underhåll + slutbehandling)</div><p>Alla faktorer anges i g CO₂e per fordonskilometer. Ton fås genom division med 1 000 000. För en vägdel är trafikarbetet längd i kilometer × ÅDT × antal kalenderdygn × fordonsklassens andel. År 2024 har 366 dygn. Energifaktorer beräknas med MJ/km eller kWh/km. Fordonsproduktion i kg CO₂e divideras med livslängdens totala kilometer. För el räknas laddförluster med. Laddhybridens verkliga elandel kan ändras.</p><p>Referensfaktorerna för fossila bränslekomponenter kommer från EU 2023/1185. De fysiska bränsleblandningarna, biofaktorerna och merparten av fordonsparametrarna är öppna utvecklingsantaganden. Boverkets 37 g/kWh är ett valbart elreferensvärde. De ska ersättas med tids- och fordonsrepresentativa faktorer före skarp användning. Ett nybilsresultat med framtida elmix, exempelvis i ICCT:s 2025-rapport, är inte ett direkt emissionsvärde för hela den befintliga flottan under kalenderåret 2024.</p><h2>Inlästa GIS-underlag i version 1.1</h2><p>Bifogade DeSO-filer innehåller 209 områden i Malmö och 84 i Helsingborg, version 2025_v2 och referensdatum 2025-01-01. De ursprungliga koordinatsystemen skiljer sig: SWEREF99 TM i Malmö och SWEREF99 13 30 i Helsingborg. Filerna är transformerade separat till geografiska koordinater. GIS-kontrollen och reproducerbar konverteringskod ingår i paketet.</p><p>Trafikår 2024 och gränsversion 2025 redovisas separat. Om 2024 års väglänkstrafik tillkommer fördelas den på 2025 års geografi. Det är en retrospektiv geografisk fördelning, ingen automatisk omräkning av gammal DeSO-statistik. Den tidigare bilmodellens 12 Malmö- och 10 Helsingborgsgrupperingar används som modellområden och är inte verifierade som kommunernas nuvarande administrativa indelning. Dess hushållskörsträckor för 2023 används inte som trafik inom områdena.</p><h2>Geografisk fördelning</h2><p>Vägens linjer delas vid varje korsning med områdenas polygonkanter. Varje delsträckas mittpunkt bestämmer DeSO och stadsdelsområde. Polygonhål och multipolygoner stöds. Längd beräknas sfäriskt med haversine; kartlinjer och gränser tolkas som raka sträckor i longitud/latitud. För tät segmentering i dessa kommuner är detta en screeningmetod, inte en lantmäteriteknisk geodesi.</p><p>Sträckor utanför samtliga importerade kommunområden tas bort. Där en nivå saknar täckning hamnar trafiken i ”Ej områdesfördelat”. Vägar exakt på gemensam gräns tilldelas det lägsta områdes-ID:t och får en kontrollnotering. Verkliga polygonöverlapp bör korrigeras före användning. Ett område helt utan kopplad länktrafik får ett tomt resultat, inte ett påstått nollutsläpp.</p><p>DeSO- och stadsdelsnivån beräknas från samma vägdelar. En godtycklig arealandel eller en majoritetskoppling mellan DeSO och stadsdel används inte. Summan av områden inklusive ej fördelade poster är kommunens resultat, i varje Monte Carlo-dragning.</p><h2>Två beräkningslägen</h2><p>I <strong>nätläget</strong> används inlagda trafikmängder utan normalisering till kommunens utsläpp. Där ÅDT saknas sätts schabloner per vägklass. I <strong>kalibrerat läge</strong> skalas basfallets trafikarbete i tre grupper så att gruppens direktutsläpp motsvarar en dokumenterad kommunreferens för samma år. Grupperna är lätt trafik, tung utan släp och tung med släp. Bussar behöver eget trafikarbete och kan inte härledas från noll i en direktutsläppstabell. Huvudregeln är att referensens fordonskategorier och gasomfattning ska matchas mot modellens innan resultaten används skarpt.</p><p>Startfallet för Malmö använder 268,3 kton CO₂e för 2024 ur den särskilda trafikslagstabellen: 183,8 + 65,4 + 19,1 kton, samt en separat busskilometerschablon. Tabellen är territoriell och innehåller ingen full fordons-LCA. Den nyare bredare kommunserien anger ett avvikande värde, 291 kton för vägtrafik 2024. Skillnaden behöver utredas med kommunen. Att ett kalibrerat resultat matchar referensen är en följd av metoden, inte en oberoende validering.</p><p>Kalibreringen räknas på basflottan. En scenarioförändring i trafikmängd eller elektrifiering kalibreras därför inte bort. Ändrar du i stället själva basflottans antaganden sker en ny basomräkning, vilket bör göras endast med stöd i basårets underlag. Byte av kalenderår ändrar inte automatiskt bränsleblandning, fordonsmix eller elmix.</p><h2>Statistisk osäkerhetsanalys</h2><p>Monte Carlo-analysen använder reproducerbara slumptal och positiva lognormalfördelade faktorer med förväntat värde 1. Förbrukning, tillverkning, livslängd, el och bränslens tidigare led är gemensamma faktorer som påverkar alla områden. Drivlinemixen samplas med en Dirichletfördelning så att andelarna förblir positiva och summerar till ett. Den samplade mixen är gemensam inom varje fordonsklass.</p><p>Trafikens osäkerhet har en gemensam stadsfaktor, en vägklassfaktor, en DeSO-faktor och en lokal faktor. För att begränsa datamängd och undvika falsk precision samlas länkar i celler med samma kommun, DeSO, stadsdelsområde, vägklass och kvalitetsklass. Den lokala osäkerheten är helt gemensam inom en sådan cell. Det är ett konservativt klusterantagande, inte en uppmätt korrelationsstruktur. I kalibrerat läge normaliseras gruppens aktivitet i varje dragning till det samplade referensutsläppet; geografiska vikter kan ändras utan att gruppsumman drivs iväg av samma trafikfel en gång till.</p><p>Kommunens fördelning beräknas genom att summera områdenas utsläpp inom respektive dragning. Nedre och övre gränser är percentilerna P2,5 och P97,5. De ska inte summeras mellan områden. Basfall och scenario använder samma slumpdragningar, så osäkerheten i deras skillnad kan beräknas direkt. Simulerat medelvärde och median kan avvika från det deterministiska huvudvärdet, bland annat eftersom livslängd ingår i en kvot.</p><p><strong>Alla standardvärden för CV och korrelation är antagna.</strong> Intervallet är ett villkorat modellintervall, inte ett empiriskt konfidensintervall och inte en garanti om 95 % sannolik täckning av sanningen. Okända vägar, systematiska fel i kategorier, felaktig historik, verkliga drivmönster och andra strukturfel kan ligga utanför intervallet. Fler simuleringar reparerar inte bristande data.</p><h2>Biogent kol och återvinning</h2><p>Biogen CO₂ vid förbränning hålls som separat informationspost. Biomassans produktion, transporter och andra växthusgaser ingår via bränslefaktorer och en öppen schablon för övrig TTW. Det innebär inte att allt biobränsle har noll klimatpåverkan eller att en fullständig tidsupplöst biogen kolbalans har genomförts. Metanläckage och markanvändningsförändring ska täckas av inlagda faktorer när de är relevanta.</p><h2>Datakvalitet före kommunal användning</h2><p>För en skarp inventering behövs ett heltäckande trafikmodellsnät som inkluderar statliga och kommunala vägar, rätt körriktning och årsrepresentativa trafikflöden; lokala drift- och bränsleandelar i trafikarbetet; busskilometer och en matchad referensinventering. Stäm av trafikarbete och direktutsläpp separat, granska extrema kalibreringsfaktorer, kontrollera större genomfartsleder och validera lokala områden mot oberoende mätningar. OSM:s aktuella nät behöver granskas mot 2024 om det året beräknas.</p><p>Malmös 136 delområden eller 14 GeSO och Helsingborgs 44 B-områden är möjliga stadsdelsindelningar. Modellen importerar kommunens gränser. Malmös gamla tio stadsdelsförvaltningar gäller 1996–2013 och ska inte märkas som dagens administrativa stadsdelar. RegSO är inte automatiskt samma sak som kommunens stadsdelsområden.</p><h2>Lokal körning och Netlify</h2><p>HTML-filen innehåller modell, gränssnitt och aktuella indata. Dubbelklicka för att köra den lokalt. Ingen beräkningsserver, extern kod, bakgrundskarta, spårning eller automatisk nätanslutning behövs. Hämtning av öppna data görs bara efter ett uttryckligt knapptryck. Spara ett projekt eller en ny offlinekopia efter lyckad hämtning. Netlify-mappen innehåller samma statiska modell och kan publiceras som en vanlig manuell deploy. En lokal fil gör inga anrop till Netlify.</p><h2>Referenser</h2><p class="small">Webbkällor kontrollerade 19 oktober 2026. Parametrarnas faktiska användning och begränsningar anges vid varje källa.</p><div id="source-list"></div></article>`;
function methodView(){return METHOD;}
function render(){window.VagvisMaps.dispose();updateHeader();$('view').innerHTML=({overview,parameters,map:activeModel==='household'?householdMapView:mapView,data:dataView,method:methodView,measures:measuresView,control:controlView,calc:calcView}[currentView])();if(currentView==='overview')histogram();if(currentView==='map')drawMap();if(currentView==='parameters'&&paramTab==='area')asRefresh();if(currentView==='method')$('source-list').innerHTML=V.SOURCES.map(s=>'<div class="source"><strong>'+esc(s.title)+'</strong><p>'+esc(s.use)+'</p>'+(s.url?'<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">Öppna källa ↗</a>':'Utvecklingsantagande · inga anspråk på empiriskt skattat värde.')+'</div>').join('');}
function setBusy(value){busy=value;$('run').disabled=value;$('cancel').disabled=!value;document.querySelectorAll('.nav').forEach(b=>b.disabled=value);document.querySelectorAll('#city button').forEach(b=>b.disabled=value);$('export').disabled=value||dirty;$('progress-box').hidden=!value;document.querySelectorAll('[data-model]').forEach(b=>b.disabled=value);$('view').style.pointerEvents=value?'none':'';}
async function run(){if(busy)return;let cc,pp;try{cc=V.config(cfg);pp=V.validateProject(project);}catch(e){message(e.message,'error');return;}cfg=cc;setBusy(true);message('');$('progress-bar').style.width='0%';$('progress-label').textContent=activeModel==='household'?'Summerar hushållens körning och simulerar …':'Delar vägar vid områdesgränser och simulerar …';try{let r;if(window.Worker){r=await new Promise((resolve,reject)=>{const source='var window=self;\n'+['v7-atgarder','v7-osakerhet','v7-mc'].map(id=>$(id).textContent).join('\n')+'\n'+$('core-script').textContent+'\n'+$('household-script').textContent+'\nself.onmessage=async e=>{try{const r=await (e.data.project.model==="household"?VagvisHouseholds:Vagvis).simulate(e.data.project,e.data.config,p=>self.postMessage({progress:p}));self.postMessage({result:r});}catch(err){self.postMessage({error:err.message});}};';const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));worker=new Worker(url);URL.revokeObjectURL(url);worker.onmessage=e=>{if(e.data.error)reject(new Error(e.data.error));else if(e.data.result)resolve(e.data.result);else{$('progress-bar').style.width=Math.round(e.data.progress*100)+'%';$('progress-label').textContent='Osäkerhetsanalys · '+Math.round(e.data.progress*100)+' %';}};worker.onerror=e=>reject(new Error(e.message||'Webbläsarens arbetsprocess kunde inte starta.'));worker._reject=reject;worker.postMessage({project:pp,config:cc});});}else r=await (activeModel==='household'?window.VagvisHouseholds:V).simulate(pp,cc,p=>$('progress-bar').style.width=p*100+'%');if(r.model==='household'){try{r.v7interval=HH().v7Interval(pp,cc,window.MC);}catch(err){r.v7interval=null;}}result=r;dirty=false;if(worker){worker.terminate();worker=null;}render();}catch(e){message(e.message,'error');}finally{if(worker){worker.terminate();worker=null;}setBusy(false);updateHeader();}}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function auditProject(){const p=V.clone(project);p.config=V.config(cfg);p.sources=V.SOURCES;p.modelVersion=V.VERSION;if(result&&!dirty){const {draws,...receipt}=result;p.lastResult=receipt;}return p;}
