function saveOffline(){try{const snapshot={...states,[activeModel]:{project:auditProject(),cfg}},a=snapshot.territorial||{project:initialProject,cfg:V.config(initialConfig)},b=snapshot.household||{project:initialHouseholdProject,cfg:V.config(initialHouseholdProject.config)},html=document.documentElement.cloneNode(true),safe=x=>JSON.stringify(x).replaceAll('<','\\u003c');a.cfg=asApply('territorial',V.clone(a.cfg));b.cfg=asApply('household',V.clone(b.cfg));html.querySelector('#embedded-project').textContent=safe(a.project);html.querySelector('#embedded-config').textContent=safe(a.cfg);html.querySelector('#embedded-household-project').textContent=safe({...b.project,config:b.cfg});html.querySelector('#embedded-mode').textContent=safe({model:activeModel});html.querySelector('#view').innerHTML='';html.querySelector('#message').innerHTML='';html.querySelector('#export-dialog').removeAttribute('open');html.querySelector('#progress-box').setAttribute('hidden','');download('Vagvis_2.0_egen_kopia.html','<!doctype html>\n'+html.outerHTML,'text/html;charset=utf-8');}catch(e){message(e.message,'error');}}
